  "guide.pulse.survivalTitle": "ꯁꯔꯚꯥꯏꯚꯜ ꯔꯅꯋꯦ꯫",
  "guide.pulse.survivalText": "ꯀꯔꯤꯒꯨꯝꯕꯥ ꯉꯁꯤ ꯅꯍꯥꯛꯅꯥ ꯏꯅꯀꯝ ꯄꯨꯝꯅꯃꯛ ꯃꯥꯡꯈꯤꯕꯥ ꯇꯥꯔꯕꯗꯤ, ꯅꯍꯥꯛꯅꯥ ꯁꯦꯚꯤꯡꯁꯤꯡꯗꯒꯤ ꯅꯍꯥꯛꯀꯤ ꯑꯣꯕꯂꯤꯒꯦꯁꯅꯁꯤꯡ ꯑꯗꯨ ꯊꯥ ꯀꯌꯥ ꯀꯣꯀꯍꯅꯕꯥ ꯉꯃꯒꯅꯤ? ꯊꯥ ꯶+ ꯑꯁꯤ ꯄꯥꯟꯗꯝ ꯊꯝꯂꯤ꯫",
